/* Reset */
*, *::before, *::after { box-sizing: border-box; margin:0; padding:0; }

html { font-size: 100%; scroll-behavior: smooth; }

body { font-family: system-ui, sans-serif; line-height: 1.5; background:#fafafa; color:#222; }

a { color:inherit; text-decoration:none; }

img { max-width:100%; display:block; }

.skip-link { position:absolute; left:-999px; top:auto; width:1px; height:1px; overflow:hidden; }
.skip-link:focus { left:1rem; top:1rem; background:#fff; color:#000; padding:.5rem 1rem; z-index:100; }

header, nav, main, footer { display:block; }

.site-header { background:#003366; color:#fff; padding:1rem; }
.site-header .site-title { font-size:1.5rem; font-weight:bold; }

.primary-nav { background:#004080; }
.primary-nav ul { list-style:none; display:flex; flex-wrap:wrap; gap:.5rem; }
.primary-nav a { display:block; padding:.5rem 1rem; color:#fff; }
.primary-nav a:hover, .primary-nav a:focus { background:#0055a5; }

.breadcrumb { background:#eaeaea; padding:.5rem 1rem; font-size:.9rem; }
.breadcrumb a { color:#0066cc; }

.main-content { padding:1rem; max-width:80ch; margin:0 auto; }

.article-card { border:1px solid #ddd; border-radius:.5rem; overflow:hidden; margin-bottom:1rem; background:#fff; }
.article-card img { height:120px; object-fit:cover; }
.article-card .card-body { padding:1rem; }
.article-card h3 { margin:0 0 .5rem; font-size:1.25rem; }
.article-card .timestamp { color:#666; font-size:.875rem; }

.latest-tabs { display:flex; gap:.5rem; margin-bottom:1rem; }
.latest-tabs button { flex:1; padding:.5rem; background:#eee; border:none; cursor:pointer; }
.latest-tabs button[aria-selected="true"] { background:#004080; color:#fff; }

.newsletter-signup { display:flex; gap:.5rem; flex-wrap:wrap; }
.newsletter-signup input[type="email"] { flex:1 1 200px; padding:.5rem; }
.newsletter-signup button { padding:.5rem 1rem; }

.subscription-form { display:grid; gap:.5rem; }
.subscription-form label { display:flex; flex-direction:column; }
.subscription-form select, .subscription-form input[type="submit"] { padding:.5rem; }

.site-footer { background:#222; color:#ddd; padding:1.5rem; font-size:.9rem; }
.site-footer a { color:#fff; }

@media (max-width:375px) {
  .primary-nav ul { flex-direction:column; }
}

/* focus-visible */
button:focus-visible, input:focus-visible, select:focus-visible, a:focus-visible { outline:2px solid #0060df; outline-offset:2px; }

/* error message */
.error-message { color:#b00020; background:#ffe6e6; padding:.5rem; border:1px solid #b00020; margin-top:.5rem; display:none; }

/* success message */
.success-message { color:#006400; background:#e6ffe6; padding:.5rem; border:1px solid #006400; margin-top:.5rem; display:none; }

/* modal */
.modal { position:fixed; inset:0; background:rgba(0,0,0,.5); display:none; align-items:center; justify-content:center; }
.modal[aria-hidden="false"] { display:flex; }
.modal-content { background:#fff; padding:2rem; border-radius:.5rem; width:90%; max-width:400px; position:relative; }
.modal-close { position:absolute; top:.5rem; right:.5rem; background:none; border:none; font-size:1.5rem; line-height:1; cursor:pointer; }
